+function timeoutError(message) {
+  const err = new Error(message);
+  err.code = 'TIMEOUT';
+  return err;
+}
+
+export async function listTools() {
+  return [{
+    name: 'slow_operation',
+    description: 'Perform a slow operation that completes within the request timeout or rejects with TIMEOUT.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        request_id: { type: 'string', description: 'Identifier for the request.' },
+        delay_ms: {
+          type: 'integer',
+          minimum: 0,
+          description: 'Simulated delay in milliseconds. Values 0..50 complete; above 50 time out.'
+        }
+      },
+      required: ['request_id'],
+      additionalProperties: false
+    }
+  }];
+}
+
+export async function callTool(name, args) {
+  if (name !== 'slow_operation') {
+    throw paramError(`Unknown tool: ${name}`);
+  }
+  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
+    throw paramError('Arguments must be an object');
+  }
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_FIELDS.has(key)) {
+      throw paramError(`Unexpected field: ${key}`);
+    }
+  }
+  if (!('request_id' in args) || args.request_id === undefined || args.request_id === null) {
+    throw paramError('Missing required field: request_id');
+  }
+  let delay_ms = 0;
+  if ('delay_ms' in args) {
+    delay_ms = args.delay_ms;
+    if (!Number.isInteger(delay_ms)) {
+      throw paramError('delay_ms must be an integer');
+    }
+    if (delay_ms < 0) {
+      throw paramError('delay_ms must be non-negative');
+    }
+  }
+  if (delay_ms > MAX_DELAY) {
+    throw timeoutError(`delay_ms ${delay_ms} exceeds the ${MAX_DELAY}ms request timeout`);
+  }
+  if (delay_ms > 0) {
+    await new Promise(resolve => setTimeout(resolve, delay_ms));
+  }
+  return { content: [{ type: 'text', text: 'completed' }] };
